// 将转换后的环境png贴图赋值给变量
const envTextureDataURI = 'data:image/png;base64,';
// 全局变量
let scene, camera, renderer, controls, mainModel;
let isExamMode = false;
let isTrainingMode = true;


// 初始化场景
function init() {
    // 创建场景
    scene = new THREE.Scene();

    // 添加环境光
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);

    // 添加平行光
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(1, 1, 1);
    scene.add(directionalLight);

    // 创建相机
    camera = new THREE.PerspectiveCamera(75, (window.innerWidth - 300) / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 1, 3);

    // 创建渲染器
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth - 300, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1;
    document.getElementById('scene-container').appendChild(renderer.domElement);

    // 初始化控制器
    initControls();

    //添加地面
    const groundGeometry = new THREE.PlaneGeometry(10, 10);
    const groundMaterial = new THREE.MeshStandardMaterial({ 
        color: 0x888888,
        roughness: 0.8,
        metalness: 0.2,
        transparent: true,
        opacity: 0 // 可按需调整透明度，范围 0 到 1
    });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    scene.add(ground);

    // 初始化物品栏
    initInventory();

    // 初始化计时器
    initTimer();

    // 事件监听
    window.addEventListener('resize', onWindowResize);

    // 开始动画循环
    animate();
}    

const envTexture = new THREE.TextureLoader().load(
    envTextureDataURI, 
    function(texture) {
        texture.mapping = THREE.EquirectangularReflectionMapping;
        scene.background = texture;
        scene.environment = texture;
    },
    undefined, 
    function(err) {
        console.error('加载环境贴图失败:', err);
        // 使用默认背景色
        scene.background = new THREE.Color(0x333333);
    }
);
// 窗口大小调整
function onWindowResize() {
    camera.aspect = (window.innerWidth - 300) / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth - 300, window.innerHeight);
}

// 动画循环
function animate() {
    requestAnimationFrame(animate);
    
    // 更新控制器
    if (controls) {
        controls.update();
    }
    
    // 更新跟随模型的逻辑
    updateFollowingModel();
    
    renderer.render(scene, camera);
}

// 初始化
init();